import{z as A,x as d,o,c as B,q as r,j as s,D as E,d as l,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"AQM：RED 与 CoDel","description":"","frontmatter":{"title":"AQM：RED 与 CoDel","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aqm-red-codel.md","filePath":"cs/aqm-red-codel.md","lastUpdated":1791413859000}'),D={name:"cs/aqm-red-codel.md"};function C(p,a,c,m,h,u){const t=d("Mermaid");return o(),B("div",null,[a[2]||(a[2]=r('<h1 id="aqm-red-与-codel" tabindex="-1">AQM：RED 与 CoDel <a class="header-anchor" href="#aqm-red-与-codel" aria-label="Permalink to &quot;AQM：RED 与 CoDel&quot;">​</a></h1><div class="epigraph"><p>尾丢把队列撑满才说话；主动队列管理提前丢或标记，给 AIMD 信号，并压住延迟。</p><footer>—— 据 Floyd and Jacobson, RED, IEEE/ACM ToN 1993；Nichols and Jacobson, CoDel, ACM Queue 2012；RFC 8289 整理</footer></div><p><a href="/cs/cc-fairness-rtt">RTT 不公平</a> 与 <a href="/cs/incast">incast</a> 都怪队列。<a href="/cs/cc-fairness-rtt">上一课</a> 留下调度器与 AQM 两条路。缺口是 <strong>RED/CoDel</strong>：按平均队列或驻留时间丢/标。本课不把 ECN 协商写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>尾丢 = 满了才丢，信号晚、同步多流一起 MD。RED：平均队列在 min/max 间概率丢。难调，平均队列不是延迟。CoDel：测包的驻留，超过 target 一段时间则丢，参数按时间不是按包数，适配带宽变化。PIE 同类。数据中心浅阈标记更近 DCTCP，公网盒常 CoDel/FQ-CoDel。</p><p>不要把 AQM 写成提高 \\(C\\)：它管的是延迟与信号时机。</p><p><span class="marginnote">直觉类比：尾丢像餐厅直到撞门才赶人——门口一满就把在场所有人一起赶走（全局同步），下一波又同时涌回。AQM 是提前小规模劝退几位：队伍始终流动，没人需要整场推倒重来，这正是 AIMD 想要的早期信号。</span></p><p><span class="marginnote">RFC 7567 AQM 建议。RFC 8289 CoDel。本课不把 RED 权值当考试。</span></p><h3 id="早期信号换浅延迟" tabindex="-1">早期信号换浅延迟 <a class="header-anchor" href="#早期信号换浅延迟" aria-label="Permalink to &quot;早期信号换浅延迟&quot;">​</a></h3><p>不增加 \\(C\\)。RED 按深度难调；CoDel 按驻留。FQ-CoDel 顺带隔离流。极浅 cut-through 无队列可管。</p><p><span class="marginnote">术语翻译：驻留时间就是一张快递单在网点积压的时长——入队到出队之间隔了多久。CoDel 不数仓库堆了多少件（深度），只看件压了多久：超过 target（默认 5 ms）还降不下来才动手。参数以时间为单位，带宽换了也不用重调，这是它比 RED 好养的地方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：尾丢 / RED / CoDel。画：入队 → 测延迟 → 超阈则丢或 CE。与 PFC：一个丢/标，一个暂停，对象都是队列，哲学相反。</p>',13)),(o(),s(i,null,{default:E(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%98%9F%E5%88%97%22%5D%20--%3E%20TAIL%5B%22%E5%B0%BE%E4%B8%A2%3A%20%E6%BB%A1%E6%89%8D%E4%B8%A2%22%5D%0A%20%20Q%20--%3E%20RED%5B%22RED%3A%20%E5%B9%B3%E5%9D%87%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20CD%5B%22CoDel%3A%20%E9%A9%BB%E7%95%99%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"FQ-CoDel 每流队列再 CoDel，顺带修 RTT 不公平与缓冲膨胀。交换机 ASIC 未必能每流，数据中心用简单阈。卫星：CoDel target 要大于固有 RTT 的排队部分，不能把传播时延当膨胀。P4 可实现自定义 AQM。",-1)),a[5]||(a[5]=e("p",null,"同步：随机早期丢减少全局同步，几何上仍 AIMD。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为队列越长吞吐越高。实际上队列只在瓶颈短暂空闲时兜缓冲，长过头的队列只是把包泡在延迟里（缓冲膨胀）：10 Mbps 链路上 1 MB 缓冲能多压约 0.8 秒延迟，吞吐却一点不涨。AQM 治的正是这个，而不是提速。")],-1)),(o(),s(i,null,{default:E(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DQ%5B%22%E5%87%BA%E9%98%9F%E4%B8%80%E4%B8%AA%E5%8C%85%22%5D%20--%3E%20SOJ%5B%22%E7%8E%B0%E5%9C%A8%E6%97%B6%E9%97%B4%E5%87%8F%E5%85%A5%E9%98%9F%E6%97%B6%E9%97%B4%20%3D%20%E9%A9%BB%E7%95%99%22%5D%0A%20%20SOJ%20--%3E%20CMP%7B%22%E9%A9%BB%E7%95%99%20%E2%89%A4%20target%3F%22%7D%0A%20%20CMP%20--%3E%7C%E6%98%AF%7C%20KEEP%5B%22%E6%AD%A3%E5%B8%B8%E5%8F%91%E9%80%81%22%5D%0A%20%20CMP%20--%3E%7C%E5%90%A6%7C%20W%7B%22%E8%B6%85%20target%20%E5%B7%B2%E6%8C%81%E7%BB%AD%E8%B6%85%E8%BF%87%20interval%3F%22%7D%0A%20%20W%20--%3E%7C%E5%90%A6%7C%20KEEP%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20DROP%5B%22%E4%B8%A2%E5%8C%85%E6%88%96%E6%89%93%20CE%20%E6%A0%87%E8%AE%B0%22%5D%0A%20%20DROP%20--%3E%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E4%B8%A2%E5%8C%85%E7%8A%B6%E6%80%81%2C%20%E6%8C%89%E9%80%92%E5%87%8F%E9%97%B4%E9%9A%94%E4%B8%A2%2C%20%E7%9B%B4%E5%88%B0%E9%A9%BB%E7%95%99%E9%99%8D%E5%9B%9E%20target%20%E4%B8%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 L4S 双队列全文。ECN 是下一课。后课默认：AQM 用早期信号换浅延迟；参数以时间为宜。</p><p>在极浅缓冲的 cut-through 盒上 AQM 无队列可管。</p><p>下一课<a href="/cs/ecn">ECN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾丢信号晚且易同步。</li><li>RED 按深度，CoDel 按驻留。</li><li>不增加容量，改善延迟与反馈。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Floyd–Jacobson, 1993；Nichols–Jacobson；RFC 8289。</li></ul>',6))])}const T=A(D,[["render",C]]);export{R as __pageData,T as default};
